def get_districts_by_division():
    result = {}
    for district, info in BD_DT.items():
        div = info['division']
        result.setdefault(div, []).append(district)
    for div in result:
        result[div].sort()
    return dict(sorted(result.items()))

def get_upozillas(district):
    if district in BD_DT:
        return sorted(BD_DT[district]['upozillas'])
    return []